function required<T>(value: T | undefined, key: string): T { if (value === undefined) throw new Error(`Missing German Advantage display copy: ${key}`); return value; }
export function localizeAdvantageQuestion(question: AdvantageQuestion, locale: Locale): AdvantageQuestion {
  if (locale !== "de") return question;
  const copy = required(advantageGermanQuestions[question.id], question.id);
  return { ...question, title: copy.title, prompt: copy.prompt, ...(question.instruction ? { instruction: required(copy.instruction, `${question.id}.instruction`) } : {}), options: question.options.map((option) => ({ ...option, label: required(copy.options[option.id], `${question.id}.${option.id}`) })) };
}

