export function getAdvantageChapterDisplay(chapter: number, locale: Locale) { const source = required(advantageChapterCopy.find(({ id }) => id === chapter), `chapter.${chapter}`); const copy = required(germanChapters[chapter - 1], `chapter.${chapter}`); return locale === "de" ? { ...source, label: copy[0], transition: copy[1] } : source; }

