export function getAdvantageSignalDisplay(id: string, locale: Locale): AdvantageSignal {
  const source = required(advantageSignalById.get(id), `signal.${id}`);
  if (locale !== "de") return source;
  const copy = required(advantageGermanSignals[id], `signal.${id}`);
  return { ...source, label: copy[0], definition: copy[1], contexts: source.contexts.map((term) => required(germanTerms[term], `context.${term}`)), overusePatterns: source.overusePatterns.map(() => copy[2]), possibleMultipliers: source.possibleMultipliers.map((term) => required(germanTerms[term], `multiplier.${term}`)) };
}

const text = new Map<string, string>();
function register(source: string, translated: string) { text.set(source, translated); }
Object.entries(germanTerms).forEach(([source, translated]) => register(source, translated));
advantageSignals.forEach((source) => {
  const copy = getAdvantageSignalDisplay(source.id, "de");
  register(source.label, copy.label); register(source.definition, copy.definition);
  register(source.definition.charAt(0).toLowerCase() + source.definition.slice(1), copy.definition.charAt(0).toLowerCase() + copy.definition.slice(1));
  source.overusePatterns.forEach((value, index) => register(value, copy.overusePatterns[index]));
});

