type DisplayTemplate = readonly [RegExp, (...parts: string[]) => string];
const templates: readonly DisplayTemplate[] = [
  [/^(.+) in Practice$/u, (name) => `${translateAdvantageText(name)} in der Praxis`],
  [/^Look for a situation where (.+) directly helps (.+) produce a result\.$/u, (a, b) => `Suche eine Situation, in der ${translateAdvantageText(a)} direkt hilft, mit ${translateAdvantageText(b)} ein Ergebnis zu erzielen.`],
  [/^The work allows (.+) but blocks (.+)\.$/u, (a, b) => `Die Arbeit erlaubt ${translateAdvantageText(a)}, blockiert aber ${translateAdvantageText(b)}.`],
  [/^Overuse can combine (.+)\.$/u, (parts) => `Übersteuerung kann folgende Muster verbinden: ${translateAdvantageText(parts)}.`],
  [/^When this stack overfires, (.+) can become more expensive than the value they create\.$/u, (a) => `Wenn diese Kombination übersteuert, können diese Muster mehr kosten als den Wert, den sie schaffen: ${translateAdvantageText(a)}.`],
  [/^(.+) as leverage$/u, (name) => `${translateAdvantageText(name)} als Hebel`],
  [/^(.+) is not the centre of your result, but it could make (.+) travel further or become easier to use\.$/u, (name, core) => `${translateAdvantageText(name)} steht nicht im Zentrum deines Ergebnisses, könnte aber ${translateAdvantageText(core)} weitertragen oder leichter nutzbar machen.`],
  [/^Use (.+) deliberately in one (.+) situation and watch whether the outcome changes\.$/u, (name, context) => `Nutze ${translateAdvantageText(name)} bewusst in einer Situation im Kontext „${translateAdvantageText(context)}“ und beobachte, ob sich das Ergebnis verändert.`],
  [/^Today: notice the next moment when (.*) happen together\.$/u, (names) => `Heute: Achte auf den nächsten Moment, in dem ${names ? translateAdvantageText(names) : "Fähigkeiten"} zusammen auftreten.`],
  [/^This week: use (.+) on one bounded problem and record the concrete result\.$/u, (name) => `Diese Woche: Nutze ${translateAdvantageText(name)} bei einem begrenzten Problem und halte das konkrete Ergebnis fest.`],
  [/^Bigger bet: seek more (.+) work where the whole combination is useful, not only one component\.$/u, (context) => `Größerer Schritt: Suche mehr Arbeit im Kontext „${translateAdvantageText(context)}“, bei der die ganze Kombination nützlich ist und nicht nur ein Bestandteil.`],
  [/^Ask one person who has seen you work when (.+) was most useful\.$/u, (name) => `Frage eine Person, die dich bei der Arbeit erlebt hat, wann ${translateAdvantageText(name)} am nützlichsten war.`],
  [/^Temporarily add (.+) and compare the result with your usual approach\.$/u, (multiplier) => `Ergänze vorübergehend „${translateAdvantageText(multiplier)}“ und vergleiche das Ergebnis mit deinem üblichen Vorgehen.`],
  [/^Use (.+) deliberately — and keep the counterweight visible\.$/u, (name) => `Nutze ${translateAdvantageText(name)} bewusst – und behalte das Gegengewicht im Blick.`],
  [/^You seem to use (.+) and (.+)\. How do they relate\?$/u, (a, b) => `Du scheinst ${translateAdvantageText(a)} und ${translateAdvantageText(b)} zu nutzen. Wie hängen sie zusammen?`],
  [/^When (.+) come together, has that produced something concrete\?$/u, (names) => `Hat es etwas Konkretes hervorgebracht, wenn ${translateAdvantageText(names)} zusammenkommen?`],
  [/^You seem capable of (.+)\. Do you enjoy using this combination\?$/u, (name) => `Du scheinst ${translateAdvantageText(name)} einsetzen zu können. Nutzt du diese Kombination gerne?`],
  [/^Where does (.+) show up most clearly\?$/u, (name) => `Wo zeigt sich ${translateAdvantageText(name)} am deutlichsten?`],
  [/^Have other people relied on you specifically for (.+)\?$/u, (name) => `Haben andere sich speziell für ${translateAdvantageText(name)} auf dich verlassen?`],
  [/^When (.+) causes problems, what is closest\?$/u, (name) => `Was passt am ehesten, wenn ${translateAdvantageText(name)} Probleme verursacht?`],
  [/^What most determines whether (.+) produces a result\?$/u, (name) => `Was bestimmt am stärksten, ob ${translateAdvantageText(name)} ein Ergebnis hervorbringt?`],
  [/^Have you created value specifically by bridging (.+) with (.+)\?$/u, (a, b) => `Hast du speziell dadurch Wert geschaffen, dass du ${translateAdvantageText(a)} mit ${translateAdvantageText(b)} verbunden hast?`],
  [/^If you had to lose one part of (.+), which loss would change how you operate more\?$/u, (name) => `Wenn ein Teil von ${translateAdvantageText(name)} wegfallen müsste: Welcher Verlust würde dein Vorgehen stärker verändern?`],
];
register("When you're at your best, which usually comes first?", "Was kommt meistens zuerst, wenn du am besten arbeitest?");

function translateAdvantageText(source: string): string {
  const exact = text.get(source);
  if (exact !== undefined) return exact;
  for (const [pattern, render] of templates) {
    const match = source.match(pattern);
    if (match) return render(...match.slice(1));
  }
  const composedSuffix = " Your answers suggest these may become more useful when they happen together, but the interaction still deserves real-world testing.";
  if (source.endsWith(composedSuffix)) return `${translateAdvantageText(source.slice(0, -composedSuffix.length))} Deine Antworten legen nahe, dass diese Fähigkeiten gemeinsam nützlicher werden könnten. Ihr Zusammenwirken sollte aber noch im echten Leben geprüft werden.`;
  const prefix = [...text.keys()].filter((key) => key.endsWith(".") && source.startsWith(`${key} `)).sort((a, b) => b.length - a.length)[0];
  if (prefix) return `${required(text.get(prefix), prefix)} ${translateAdvantageText(source.slice(prefix.length + 1))}`;
  for (const separator of [" + ", " → ", " · ", " and ", " with "]) {
    const first = [...text.keys()].filter((key) => source.startsWith(`${key}${separator}`)).sort((a, b) => b.length - a.length)[0];
    if (first) return `${required(text.get(first), first)}${separator === " and " || separator === " with " ? " und " : separator}${translateAdvantageText(source.slice(first.length + separator.length))}`;
  }
  throw new Error("Unmapped German Advantage result display text");
}

export function localizeAdvantageCandidate(candidate: AdvantageCandidate, locale: Locale): AdvantageCandidate {
  if (locale !== "de") return candidate;
  return { ...candidate, label: translateAdvantageText(candidate.label), synthesis: translateAdvantageText(candidate.synthesis), recognition: candidate.recognition.map(translateAdvantageText), contexts: candidate.contexts.map(translateAdvantageText), killers: candidate.killers.map(translateAdvantageText), shadow: translateAdvantageText(candidate.shadow), counterweight: translateAdvantageText(candidate.counterweight), multiplier: translateAdvantageText(candidate.multiplier) };
}

export function localizeAdvantageProbes(probes: readonly AdvantageProbe[], locale: Locale): readonly AdvantageProbe[] {
  if (locale !== "de") return probes;
  return probes.map((probe) => ({ ...probe, prompt: translateAdvantageText(probe.prompt), options: probe.options.map((option) => ({ ...option, label: translateAdvantageText(option.label) })) }));
}

export function localizeAdvantageMap(map: PersonalAdvantageMap, locale: Locale): PersonalAdvantageMap {
  if (locale !== "de") return map;
  return {
    ...map,
    coreAdvantage: localizeAdvantageCandidate(map.coreAdvantage, locale),
    supportingAdvantages: map.supportingAdvantages.map((item) => localizeAdvantageCandidate(item, locale)),
    ...(map.emergingAdvantage ? { emergingAdvantage: localizeAdvantageCandidate(map.emergingAdvantage, locale) } : {}),
    stack: map.stack.map((item) => ({ ...item, label: getAdvantageSignalDisplay(item.signalId, locale).label })),
    hiddenAdvantages: map.hiddenAdvantages.map((item) => ({ label: translateAdvantageText(item.label), explanation: translateAdvantageText(item.explanation), experiment: translateAdvantageText(item.experiment) })),
    amplifierEnvironments: map.amplifierEnvironments.map(translateAdvantageText), killers: map.killers.map(translateAdvantageText), shadows: map.shadows.map(translateAdvantageText), counterweights: map.counterweights.map(translateAdvantageText),
    ...(map.missingMultiplier ? { missingMultiplier: translateAdvantageText(map.missingMultiplier) } : {}),
    evidenceSummary: map.evidenceSummary.map((item) => ({ label: translateAdvantageText(item.label), detail: translateAdvantageText(item.detail) })),
    playbook: { showsUp: map.playbook.showsUp.map(translateAdvantageText), powerfulWhen: map.playbook.powerfulWhen.map(translateAdvantageText), tryThis: map.playbook.tryThis.map(translateAdvantageText), watchFor: map.playbook.watchFor.map(translateAdvantageText) },
    experiments: map.experiments.map(translateAdvantageText), reminder: translateAdvantageText(map.reminder),
  };
}
